  source?: string;
  zapId?: string;
  // IDs por portal (expansão 5 fontes, 22/09/2026) + código da loja origem.
  vivaId?: string;
  olxId?: number;
  apolarId?: string;
  codigoAnunciante?: string;
  condoUnknown?: boolean;
  // Leva dores-consumidor (S001, aditivo — ausente = aluguel, nada quebra)
